import os,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    H,W=len(g),len(g[0])
    blocks=[]
    for i in range(H-2):
        for j in range(W-2):
            c=g[i][j]
            if c and all(g[i+a][j+b]==c for a in range(3) for b in range(3)):
                blocks.append((c,i+1,j+1))
    hrow={}; vcol={}
    for c,i,j in blocks: hrow[i]=c; vcol[j]=c
    out=[row[:] for row in g]
    for i in range(H):
        for j in range(W):
            h=v=None
            if i in hrow: h=hrow[i]
            if j in vcol: v=vcol[j]
            if h is not None and v is not None:
                out[i][j]= h if h==v else 0
            elif h is not None: out[i][j]=h
            elif v is not None: out[i][j]=v
    return out

